526	func StartTestConLimitServer(maxConnections int32) net.Listener {
527		var connections atomic.Int32
528	
529		return startTestServer(func(sl *shutdownListener) http.Handler {
530			mux := http.NewServeMux()
531			mux.HandleFunc("/"+BuildName, func(writer http.ResponseWriter, request *http.Request) {
532				defer func() {
