			useInitialDelay := delay > 0 && !timeoutOnce.Swap(true)
			rangeFileHandle(
				writer,
				request,
				nil,
				func(file *os.File, n int64) {
					if useInitialDelay {
						slowCopyAfterDelay(sl, writer, file, n, delay)
