		})
		// Good URL - returns the file successfully with range support
		mux.HandleFunc("/good-url", func(writer http.ResponseWriter, request *http.Request) {
			rangeFileHandle(
				writer,
				request,
				nil,
				func(file *os.File, n int64) {
					io.CopyN(writer, file, n)
				},
			)
		})
		return mux
