590	func defaultWebViewRPCUnixSocket() (string, error) {
591		homeDir, err := os.UserHomeDir()
592		if err != nil {
593			return "", err
594		}
595		return filepath.Join(homeDir, "gopeed_webview.sock"), nil
596	}
597	
598	type taskTerminalWaiter struct {
599		downloader *download.Downloader
600	}
601	
602	func newTaskTerminalWaiter(d *download.Downloader) *taskTerminalWaiter {
603		return &taskTerminalWaiter{downloader: d}
604	}
605	
606	func (w *taskTerminalWaiter) Register(id string) {
607	}
608	
609	func (w *taskTerminalWaiter) Wait(id string, timeout time.Duration) (*download.Task, error) {
610		deadline := time.Now().Add(timeout)
611		for time.Now().Before(deadline) {
612			if task, ok := w.currentTerminalTask(id); ok {
613				return task, w.taskError(task)
614			}
615			time.Sleep(50 * time.Millisecond)
616		}
617		return nil, fmt.Errorf("timeout waiting for task %s", id)
618	}
619	
620	func (w *taskTerminalWaiter) currentTerminalTask(id string) (*download.Task, bool) {
621		task := w.downloader.GetTask(id)
622		if task == nil {
623			return nil, false
624		}
625		if task.Status != base.DownloadStatusDone && task.Status != base.DownloadStatusError {
626			return nil, false
627		}
628		return task, true
629	}
630	
631	func (w *taskTerminalWaiter) taskError(task *download.Task) error {
632		if task == nil {
633			return fmt.Errorf("task is nil")
634		}
635		if task.Status == base.DownloadStatusError {
636			return fmt.Errorf("task %s finished with status %s", task.ID, task.Status)
637		}
638		return nil
639	}
640	
641	func startVerboseTaskListener(d *download.Downloader, files []*downloadedFileResult) func() {
642		tracked := make(map[string]string, len(files))
643		for _, file := range files {
644			tracked[file.TaskID] = file.Name
645		}
646		d.Listener(func(event *download.Event) {
647			if event == nil || event.Task == nil {
648				return
649			}
650			name, ok := tracked[event.Task.ID]
651			if !ok {
652				return
653			}
654			switch event.Key {
655			case download.EventKeyStart, download.EventKeyProgress, download.EventKeyDone, download.EventKeyError:
656				printVerboseTaskEvent(event, name)
657			}
658		})
659		return func() {}
660	}
661	
662	func printVerboseTaskEvent(event *download.Event, name string) {
663		task := event.Task
664		ts := time.Now().Format("15:04:05.000")
665		if task == nil {
666			return
667		}
668		total := int64(0)
669		if task.Meta != nil && task.Meta.Res != nil {
670			total = task.Meta.Res.Size
671		}
672		downloaded := int64(0)
673		speed := int64(0)
674		if task.Progress != nil {
675			downloaded = task.Progress.Downloaded
676			speed = task.Progress.Speed
677		}
678		if event.Key == download.EventKeyError && event.Err != nil {
679			fmt.Fprintf(
680				os.Stderr,
681				"[%s] event=%s task=%s status=%s downloaded=%d total=%d speed=%d name=%q err=%v\n",
682				ts,
683				event.Key,
684				task.ID,
685				task.Status,
686				downloaded,
687				total,
688				speed,
689				name,
690				event.Err,
691			)
692			return
693		}
694		fmt.Fprintf(
695			os.Stderr,
696			"[%s] event=%s task=%s status=%s downloaded=%d total=%d speed=%d name=%q\n",
697			ts,
698			event.Key,
699			task.ID,
700			task.Status,
701			downloaded,
702			total,
703			speed,
704			name,
705		)
706	}
707	
708	func printJSON(v any, pretty bool) error {
709		var (
710			data []byte
711			err  error
712		)
713		if pretty {
714			data, err = json.MarshalIndent(v, "", "  ")
715		} else {
716			data, err = json.Marshal(v)
717		}
718		if err != nil {
719			return err
720		}
721		fmt.Println(string(data))
722		return nil
723	}
