55		requestType := reflect.TypeOf((*ExtensionTaskRequest)(nil))
56		for _, name := range []string{"SetUrl", "SetLabels", "PutLabel", "DelLabel", "SetMethod", "SetBody", "SetHeaders", "PutHeader", "DelHeader", "SetTrackers"} {
57			if _, ok := requestType.MethodByName(name); !ok {
58				t.Fatalf("request wrapper does not expose %s", name)
59			}
60		}
61		for _, typ := range []reflect.Type{reflect.TypeOf(ExtensionTask{}), reflect.TypeOf(OnErrorExtensionTask{})} {
62			if _, ok := typ.FieldByName("Req"); ok {
63				t.Fatalf("%v exposes the removed task.req entry", typ)
64			}
65			field, ok := typ.FieldByName("Meta")
66			if !ok || field.Type != reflect.TypeOf((*ExtensionTaskMeta)(nil)) {
67				t.Fatalf("%v has no metadata wrapper", typ)
68			}
69		}
70		field, ok := reflect.TypeOf(ExtensionTaskMeta{}).FieldByName("Req")
71		if !ok || field.Type != requestType {
72			t.Fatal("meta.req has no request wrapper")
73		}
74		if _, ok := taskType.MethodByName("Continue"); ok {
75			t.Fatal("regular task unexpectedly exposes Continue")
76		}
77		if _, ok := taskType.MethodByName("SetUrl"); ok {
78			t.Fatal("regular task unexpectedly exposes SetUrl")
79		}
80	
81		extensionTaskType := reflect.TypeOf((*ExtensionTask)(nil))
82		for _, typ := range []reflect.Type{extensionTaskType, reflect.TypeOf((*OnErrorExtensionTask)(nil))} {
83			if _, ok := typ.MethodByName("SetUrl"); !ok {
84				t.Fatalf("%v does not expose the deprecated SetUrl alias", typ)
85			}
86		}
87		if _, ok := extensionTaskType.MethodByName("Continue"); ok {
88			t.Fatal("non-error extension task unexpectedly exposes Continue")
89		}
90	
91		errorTaskType := reflect.TypeOf((*OnErrorExtensionTask)(nil))
92		if _, ok := errorTaskType.MethodByName("Continue"); !ok {
93			t.Fatal("onError task does not expose Continue")
94		}
95	
96		startTaskField, _ := reflect.TypeOf(OnStartContext{}).FieldByName("Task")
97		if startTaskField.Type != extensionTaskType {
98			t.Fatalf("onStart does not inject the request mutation wrapper: %v", startTaskField.Type)
99		}
100		doneTaskField, _ := reflect.TypeOf(OnDoneContext{}).FieldByName("Task")
101		if doneTaskField.Type != taskType {
102			t.Fatalf("onDone unexpectedly injects a mutation wrapper: %v", doneTaskField.Type)
103		}
104		errorTaskField, _ := reflect.TypeOf(OnErrorContext{}).FieldByName("Task")
105		if errorTaskField.Type != errorTaskType {
106			t.Fatalf("onError does not inject the recovery wrapper: %v", errorTaskField.Type)
107		}
108	}
